#include "types.h"

typedef struct {
    u8 flag[3];
    u8 rest[53];
} Girl;

typedef struct {
    u8 pad0[0x1D2];
    Girl girl[60];
    u8 pad1[0xF5E - 0x1D2 - 60 * 56];
    u8 day;
    u8 sel;
} Save;

extern Save screen_w;

extern u8 now_girl;
extern short now_serifu;
